        for c in range(W):
            if grid[r][c] == target_color and (r,c) not in visited:
                comp = []
                q = deque([(r,c)])
                visited.add((r,c))
                while q:
                    cr, cc = q.popleft()
                    comp.append((cr, cc))
                    for dr, dc in dims:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == target_color and (nr,nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                comps.append(sorted(comp))
    return comps

def canonical(comp):
    if len(comp) == 0: return ()
    mr, mc = min(r for r, c in comp), min(c for r, c in comp)
    return tuple(sorted((r - mr, c - mc) for r, c in comp))

